import{requireUser}from"@/lib/auth/guards";import{db}from"@/lib/db";import{uploadAction}from"@/app/actions";import{categoryLabel}from"@/lib/i18n";import{getLocale,getMessages}from"@/lib/i18n-server";export default async function Upload(){await requireUser();const[cats,locale,m]=await Promise.all([db.category.findMany({where:{isActive:true}}),getLocale(),getMessages()]);return <section className="auth wide"><form action={uploadAction} className="panel" encType="multipart/form-data"><span className="eyebrow">{m.newPublication}</span><h1>{m.uploadTitle}</h1><input type="hidden" name="sourceLocale" value={locale}/><label className="drop">{m.imageHint}<input name="file" type="file" accept="image/jpeg,image/png,image/webp" required/></label><label>{m.title}<input name="title" minLength={2} maxLength={100} required/></label><label>{m.description}<textarea name="description" maxLength={2000}/></label><label>{m.category}<select name="categoryId"><option value="">{m.noCategory}</option>{cats.map(c=><option key={c.id} value={c.id}>{categoryLabel(c.slug,locale,c).name}</option>)}</select></label><label>{m.tags}<input name="tags"/></label><fieldset><legend>{m.policy}</legend><label><input type="checkbox" name="adults" required/> {m.adultsPolicy}</label><label><input type="checkbox" name="consensual" required/> {m.consentPolicy}</label><label><input type="checkbox" name="noDeepfake" required/> {m.deepfakePolicy}</label></fieldset><button>{m.saveDraft}</button></form></section>}